// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/templates", wrapper.ListAssessmentTemplates)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/templates", wrapper.CreateAssessmentTemplate)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/domain-verifications", wrapper.ListVerifications)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/domain-verifications", wrapper.StartVerification)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/domain-verifications/{id}/check", wrapper.CheckVerification)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/authorizations", wrapper.ListAuthorizations)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/authorizations", wrapper.CreateAuthorization)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/authorizations/{id}/revoke", wrapper.RevokeAuthorization)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/assessments", wrapper.ListAssessments)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/assessments", wrapper.StartAssessment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/assessments/{id}", wrapper.GetAssessment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/assessments/{id}/cancel", wrapper.CancelAssessment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/it-assessments/assessments/{id}/reports", wrapper.CreateAssessmentReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/reports/{id}", wrapper.GetAssessmentReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/it-assessments/reports/{id}/pdf", wrapper.DownloadAssessmentReport)
	})

	return r
}

